from openai import OpenAI
client = OpenAI()

while True:
    user_input = input("You: ")
    if user_input.lower() in ["exit", "quit"]:
        break
    response = client.chat.completions.create(
        model="gpt-4o",
        messages=[
            {"role": "user", "content": user_input}
        ],
        max_tokens=300
    )
    print("Bot:", response.choices[0].message.content)
